"""Build the approved Version 5 pages with the targeted Version 6 guidelines conversion."""
from pathlib import Path
from html import escape as e
import json
import re
from guidelines_document import build_guidelines

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'dist'
REV = 'v5-20260907'
assets = {int(''.join(filter(str.isdigit,r['source']))):r for r in json.loads((ROOT/'docs/asset-map.json').read_text())}
assets.update({r['key']:r for r in json.loads((ROOT/'docs/asset-map-v4.json').read_text())})
assets.update({r['key']:r for r in json.loads((ROOT/'docs/asset-map-v5.json').read_text())})

def scientific_text(text):
    return re.sub(r'\b(Sclerotinia sclerotiorum|Cercospora|Fusarium)\b', r'<i>\1</i>', e(text))

def photo(n, alt, cls='', eager=False):
    r=assets[n]; w,h=r['size']
    return f'<img src="{r["asset"]}" width="{w}" height="{h}" alt="{e(alt)}" class="{cls}" loading="{"eager" if eager else "lazy"}" decoding="async">'

def figure(n, alt, caption='', cls=''):
    r=assets[n]
    label='' if caption is None else f'<figcaption>{scientific_text(caption or alt)} <span aria-hidden="true">↗</span></figcaption>'
    return f'<figure class="scientific-figure {cls}"><a href="{r["asset"]}" target="_blank" rel="noopener" aria-label="Open full-size image: {e(alt)}">{photo(n,alt)}</a>{label}</figure>'

menus = [
 ('Research',[('All research themes','research.html'),('NLR Regulation in Plants','research.html#nlr-temperature'),('Soybean Host–Pathosystem','research.html#soybean-loci'),('Soil Microbiome and BioProducts','research.html#soil-microbial-genomics')]),
 ('Our Approach',[('Lab-to-Land Approach','index.html#approach'),('Genome Sequencing','index.html#genome-sequencing'),('Spatial Transcriptomics','index.html#spatial-transcriptomics'),('Genetic Engineering','index.html#genetic-engineering'),('Stakeholder Input','index.html#stakeholder-input'),('Institutional / Collaborative Integration','index.html#collaborative-integration')]),
 ('About the Team',[('Meet the team','team.html'),('Principal Investigator','team.html#principal-investigator'),('Graduate Students','team.html#graduate-students'),('Undergraduate Students','team.html#undergraduate-students'),('Temporary Staff','team.html#temporary-staff'),('Lab Alumni','team.html#lab-alumni')]),
 ('Outreach',[('Outreach and engagement','outreach.html'),('GeN-G & GeN-G BRING','outreach.html#gen-ng'),('Field Contact','outreach.html#field-contact'),('Industry Partnerships','outreach.html#industry')]),
 ('Funding',[('Research support','funding.html'),('Federal Programs','funding.html#federal'),('Commodity Groups','funding.html#commodity')])
]

def header(active=''):
    items=''
    for title,links in menus:
        on=' current' if title==active else ''
        items+=f'<details class="nav-dropdown{on}"><summary>{title}<span class="chevron" aria-hidden="true"></span></summary><div class="dropdown-panel">'+''.join(f'<a href="{href}">{name}</a>' for name,href in links)+'</div></details>'
    return f'''<a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="brand" href="index.html" aria-label="Solanki Lab home"><img src="assets/brand/solanki-lab.png" width="70" height="70" alt=""><span>SOLANKI <b>LAB</b></span></a><button class="nav-toggle" aria-expanded="false" aria-controls="site-nav">Menu <span aria-hidden="true">☰</span></button><nav id="site-nav" aria-label="Main navigation">{items}<a class="nav-direct {'current' if active=='Recruitment' else ''}" href="recruitment.html">Recruitment</a><a class="nav-direct {'current' if active=='Lab Guidelines' else ''}" href="guidelines.html">Lab Guidelines</a></nav></header>'''

footer='''<footer class="site-footer"><div><a class="footer-brand" href="index.html">SOLANKI LAB</a><p>Functional Genomics · Plant–Microbe–Soil Interactions</p></div><div><a href="mailto:shyam.solanki@sdstate.edu">shyam.solanki@sdstate.edu</a><address class="contact-address"><strong>Shyam Solanki, PhD</strong><br>Assistant Professor<br>Functional Genomics of Plant Microbe Soil Interaction<br>Agronomy, Horticulture, &amp; Plant Science<br>South Dakota State University<br>Berg Agricultural Hall 251, Box 2100A<br>Brookings, SD 57007<br><a href="tel:+16056885032">(605) 688-5032</a></address></div><div class="footer-links"><a href="team.html">Our team</a><a href="guidelines.html">Lab guidelines</a><a href="research.html">Research</a></div></footer>'''

def page(name,title,description,body,active='',home=False,extra_head=''):
    backdrop='<canvas id="universe" aria-hidden="true"></canvas><div class="shade" aria-hidden="true"></div>' if home else '<div class="quiet-backdrop" aria-hidden="true"></div>'
    scripts=f'<script src="site.js?{REV}" defer></script>'+(f'<script src="universe.js?{REV}" defer></script>' if home else '')
    html=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#03070b"><title>{e(title)} | Solanki Lab</title><meta name="description" content="{e(description)}"><link rel="icon" type="image/png" href="assets/brand/favicon.png"><link rel="stylesheet" href="style.css?{REV}">{extra_head}</head><body class="{'home-page' if home else 'secondary-page'}">{backdrop}{header(active)}<main id="main">{body}</main>{footer}{scripts}</body></html>'''
    (OUT/name).write_text(html)

def intro(kicker,title,text):
    return f'<section class="page-intro wrap"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="page-lead">{text}</p></section>'

