page('index.html','Functional Genomics & Plant–Microbe–Soil Interactions','Solanki Lab at South Dakota State University explores functional genomics and plant–microbe–soil interactions, from molecular discovery to crop resilience.',home,home=True)

programs=[
 {'id':'soybean-loci','title':'Soybean Disease Resistance Loci','tag':'SOYBEAN HOST–PATHOSYSTEM','color':'mint','text':'We investigate the genetic basis of soybean disease resistance by connecting variation across soybean germplasm with disease phenotypes. Soilborne diseases such as white mold and Fusarium diseases are a primary focus, while Cercospora and other foliar diseases are also being explored. Genetic mapping and comparative analyses help prioritize genomic regions and candidate genes for functional evaluation.','questions':['Which genomic regions are associated with disease resistance?','How can genetic variation guide the selection and validation of resistant germplasm?'],'figs':[(1,'Soybean genome-wide association plot across chromosomes.'),(2,'Genetic relationships among soybean accessions.') ]},
 {'id':'pathogen-genomics','title':'Pathogen Genomics and Effector Identification','tag':'PATHOGEN BIOLOGY','color':'cyan','text':'Field surveillance, pathogen characterization, and genome analysis connect disease pressure with pathogen diversity. We use these complementary perspectives to identify candidate effectors and investigate their roles in plant–pathogen interactions. We are also exploring dsRNA/RNAi-based approaches as targeted tools for next-generation plant disease management.','questions':['How does pathogen diversity relate to disease observed in the field?','Which candidate effectors contribute to interactions with the host?','How can next-generation pathogen-control strategies be further optimized and made accessible for practical disease management?'],'figs':[(3,'South Dakota soybean disease survey coverage map.'),(4,'Soybean plants evaluated under greenhouse conditions.'),('dsrna','Fluorescently labeled synthesized dsRNA attachment assay on Sclerotinia sclerotiorum mycelia.')]},
 {'id':'nlr-temperature','title':'NLR Temperature Sensitivity in Small Grains','tag':'NLR REGULATION IN PLANTS','color':'gold','text':'We study how temperature influences the function of NLR immune receptors in cereal crops. Connecting environmental conditions with resistance phenotypes helps us investigate why immune protection is maintained or weakened across temperature regimes. AI-guided prediction and modeling of temperature-sensitive motifs can help identify structural features associated with temperature-dependent immune function and guide experimentally testable changes in receptor structure.','questions':['How does temperature change NLR-mediated immunity?','Which molecular features support resistance under changing temperatures?','How can protein modeling guide testable designs for temperature-adapted immunity?'],'figs':[(5,'Cereal leaf phenotypes and associated measurements across temperature conditions.')]},
 {'id':'nlr-domain-evolution','title':'NLR Domain Evolution in Grasses and Legumes','tag':'NLR DOMAIN EVOLUTION','color':'violet','text':'We examine how immune receptor domains evolve across grasses and legumes and how that diversity relates to function.','questions':['How has domain diversity shaped immune receptor function?'],'figs':[(6,'Fluorescence microscopy of fungal structures interacting with host cells.'),('rpg5','Conceptual model of the Rpg5 NLR-ID immune receptor.')]},
 {'id':'spatial-regulation','title':'Spatial Regulation of Plant Resistance Expression Circuit','tag':'FUNCTIONAL & SPATIAL GENOMICS','color':'cyan','text':'Resistance responses unfold in particular tissues and at particular times. We integrate tissue imaging and spatial transcriptomics to connect gene expression with biological context and identify expression patterns for functional investigation.','questions':['Where are resistance-associated expression programs active?','How do tissue organization and gene expression change during plant–pathogen interaction?'],'figs':[(7,'Microscopy of sectioned wheat grain tissue.'),(8,'Annotated wheat grain tissue regions with spatial measurements.'),(9,'Spatial genomics analysis panels.') ]},
 {'id':'soil-microbial-genomics','title':'Soil Microbial Genomics','tag':'SOIL MICROBIOME & BIOPRODUCTS','color':'mint','text':'We investigate soil microbial composition and genomic potential to understand how communities relate to plant health. Sequencing and functional analysis help connect microbial diversity with nutrient use and disease suppression.','questions':['Which microbial communities and functions are associated with plant health?','How can genomic information guide the selection of beneficial microorganisms?'],'figs':[(10,'Sequencing output across soil microbial samples.')]},
 {'id':'biostimulants','title':'Biostimulants and Biocontrol','tag':'CORN · SOYBEAN · WHEAT','color':'gold','text':'We evaluate beneficial microorganisms and their products for applications in crop health. Laboratory assays, plant experiments, and local industry partnerships help develop and assess formulations aligned with farmer needs.','questions':['Which locally adapted microorganisms show beneficial activity?','How can promising biological activity translate into practical crop health formulations?'],'figs':[('biostimulant-cultures','Microbial culture assay plates arranged against a dark background.'),('soil-corn-concept','Supplied conceptual figure showing soil microbiome and corn health, research approaches, and intended outcomes.'),('fungal-culture','Fungal colony growing on agar in a Petri dish.'),('culture-comparison','Five microbial culture plates with different colony growth patterns.')]}
]
contents='<nav class="section-index" aria-label="Research theme index">'+''.join(f'<a href="#{p["id"]}"><span>0{i+1}</span>{p["title"]}</a>' for i,p in enumerate(programs))+'</nav>'
research=intro('RESEARCH / SOLANKI LAB','From genes to<br><em>crop resilience.</em>','Integrated research components in the lab connect plant immunity, pathogen biology, functional genomics, and soil microbial solutions to achieve integrative plant health in agricultural systems.')+f'<div class="wrap research-layout"><aside class="program-sidebar"><p class="eyebrow">EXPLORE RESEARCH THEMES</p>{contents}</aside><div class="programs">'
